public class SortedMergerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("mergeSorted({1,4,9}, {2,3,10})", "[1, 2, 3, 4, 9, 10]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{1, 4, 9}, new int[]{2, 3, 10})));
            check("mergeSorted({1,2}, {5,6,7}) no interleave", "[1, 2, 5, 6, 7]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{1, 2}, new int[]{5, 6, 7})));
            check("mergeSorted({}, {3,8})", "[3, 8]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{}, new int[]{3, 8})));
            check("mergeSorted({3,8}, {})", "[3, 8]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{3, 8}, new int[]{})));
            check("mergeSorted({2,2,5}, {2,6}) duplicates kept", "[2, 2, 2, 5, 6]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{2, 2, 5}, new int[]{2, 6})));
            check("mergeSorted({}, {})", "[]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{}, new int[]{})));
            check("mergeSorted({-5,0}, {-3,4}) negatives", "[-5, -3, 0, 4]",
                    java.util.Arrays.toString(SortedMerger.mergeSorted(new int[]{-5, 0}, new int[]{-3, 4})));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

