public class SortedMerger {

    public static int[] mergeSorted(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        int i = 0;
        int j = 0;
        int out = 0;
        while (i < a.length && j < b.length) {
            if (a[i] <= b[j]) {
                result[out++] = a[i++];
            } else {
                result[out++] = b[j++];
            }
        }
        while (i < a.length) {
            result[out++] = a[i++];
        }
        while (j < b.length) {
            result[out++] = b[j++];
        }
        return result;
    }
}
